// The day's affirmation in Polish, for the country pages in Polish. Written by scripts/home_extras.py from data/affirmations-i18n/; do not edit.
(function(){var D=document;if(D.getElementById("affirmations-local"))return;var e=D.createElement("script");e.type="application/json";e.id="affirmations-local";e.textContent="[\"Nie musisz dziś zrobić wszystkiego. Wystarczy następna mała rzecz.\", \"Zmęczenie to nie porażka. Jesteś zmęczona, bo każdego dnia jesteś na posterunku.\", \"Naczynia mogą poczekać. Masz prawo usiąść na pięć minut.\", \"Płatki na kolację to też nakarmienie rodziny.\", \"Na odpoczynek nie trzeba zasłużyć. Możesz odpocząć choćby teraz.\", \"Czasem zwycięstwem jest to, że wszyscy dotrwali do wieczora. To prawdziwe zwycięstwo.\", \"Robisz więcej, niż ktokolwiek widzi. Ja to widzę.\", \"Bałagan w domu i kochane dzieci. To dobra wymiana.\", \"W trudny dzień twoje „najlepiej” wygląda inaczej, ale wciąż się liczy.\", \"Jeden głęboki oddech. Opuść ramiona. Dobrze sobie radzisz.\", \"Dziś możesz obniżyć poprzeczkę. Podniesiesz ją innego dnia.\", \"Prośba o pomoc to oznaka siły, nie słabości.\", \"Masz prawo odmówić kolejnej rzeczy.\", \"Jeśli dziś czułaś się samotna, nie jesteś jedyną mamą, która tak się czuła. Jest nas dużo.\", \"Zasługujesz na przyjaciółkę, która zapyta, jak się czujesz, i poczeka na odpowiedź.\", \"Możesz odezwać się pierwsza. Większość mam czeka, aż ktoś to zrobi.\", \"To, że czujesz się niewidzialna, nie znaczy, że nie jesteś ważna. Jesteś bardzo ważna.\", \"Twoje uczucia mają sens. Nie jesteś „za bardzo”.\", \"Tutaj nie musisz tłumaczyć swojego trudnego dnia. Rozumiemy.\", \"Wiadomość do innej mamy z jednym „ja też” potrafi odmienić cały dzień.\", \"Karmienie, przewijanie, kołysanie i od nowa. To prawdziwa praca, nawet jeśli wygląda jak siedzenie w miejscu.\", \"Ty i twoje dziecko wciąż się poznajecie. Nie ma pośpiechu.\", \"Dni z noworodkiem są długie. Ten etap nie będzie trwał wiecznie.\", \"Jeśli dziś udało ci się tylko utrzymać małego człowieka najedzonego i w cieple, wykonałaś wielką pracę.\", \"Nie musisz szybko wracać do formy. Możesz po prostu być tam, gdzie jesteś.\", \"Jakkolwiek karmisz swoje dziecko, troszczysz się o nie. To się liczy.\", \"Można być niewyspaną i pełną miłości jednocześnie.\", \"Przytul dziecko i odpuść dom. Dom nigdzie nie ucieknie.\", \"Histeria w sklepie nie robi z ciebie złej mamy. To znaczy tylko, że masz małe dziecko.\", \"Maluchy sprawdzają granice, bo przy tobie czują się bezpiecznie.\", \"Dziś byłaś spokojna o minutę dłużej niż wczoraj. To się liczy.\", \"Jeśli puściły ci nerwy, przytulenie i „przepraszam” naprawiają bardzo dużo. I uczą czegoś dobrego.\", \"Lepkie rączki, głośne głosy, wielkie emocje. Wychowujesz całego człowieka.\", \"Piąte „dlaczego?” w ciągu godziny to rosnący mały umysł.\", \"Nie potrzebujesz idealnego dnia, żeby stworzyć szczęśliwe wspomnienie.\", \"Trzaśnięcie drzwiami to nie koniec historii. Zostaw zapalone światło.\", \"Twój nastolatek może tego nie mówić, ale twoja stała obecność ma znaczenie.\", \"Bycie tą spokojną w domu to ciężka praca. A ty dajesz radę.\", \"Niektóre z najlepszych rozmów odbywają się w samochodzie. Jedź dalej.\", \"Oddalają się, żeby dorosnąć, a nie żeby zostawić cię w tyle.\", \"Nie musisz znać wszystkich odpowiedzi. Słuchanie to już duża część.\", \"Starsze dzieci wciąż cię potrzebują, tylko ciszej.\", \"Samotne rodzicielstwo wymaga siły, której większość ludzi nigdy nie widzi.\", \"Jesteś wystarczająco dobrą mamą dla swojego dziecka. Zawsze byłaś.\", \"Jedna para rąk, sto zadań. Bądź dla siebie łagodna.\", \"Twoje dzieci, patrząc na ciebie, uczą się, jak wygląda silny, kochający człowiek.\", \"Przerwa to nie dezercja. Dzięki niej dajesz radę dalej.\", \"Nikt nie liczy punktów. Liczy się miłość i to, że jesteś.\", \"Żałoba i miłość biorą się z tego samego miejsca. Tęsknota pokazuje, jak bardzo kochałaś.\", \"Nie ma właściwego czasu na żałobę. Daj sobie tyle czasu, ile potrzebujesz.\", \"W trudne rocznice bądź dla siebie tak łagodna, jak byłabyś dla przyjaciółki.\", \"Możesz nosić w sobie smutek i mimo to śmiać się z dziećmi. Jedno i drugie jest prawdziwe.\", \"Jeśli straciłaś ciążę albo dziecko, ta strata jest prawdziwa i twoja miłość też.\", \"Czasem żałoba jest cicha, a czasem głośna. Jedno i drugie jest w porządku.\", \"Brak pieniędzy nie oznacza braku miłości.\", \"Twoje dzieci zapamiętają czas z tobą bardziej niż rzeczy, które kupiłaś.\", \"Pytanie o pomoc z rachunkami to mądrość, nie wstyd. Właśnie po to ta pomoc istnieje.\", \"Darmowe popołudnie w parku może być najlepszym dniem tygodnia.\", \"Udało ci się przeciągnąć budżet o jeszcze jeden tydzień. To prawdziwa umiejętność.\", \"Martwienie się o pieniądze męczy. Dźwigasz dużo, a mimo to wciąż tu jesteś.\", \"Wypiłaś dziś szklankę wody. Zacznij od tego.\", \"Wszyscy wyszli z domu. Może buty nie pasowały do siebie. I tak zwycięstwo.\", \"Wykonałaś telefon, którego się bałaś. To było odważne.\", \"Dziś się śmiałaś. Zatrzymaj to w sobie.\", \"Ciepły posiłek, czysta koszulka, bajka na dobranoc. Z małych rzeczy składa się dzieciństwo.\", \"Dziś byłaś dla kogoś dobra, nawet jeśli tylko dla siebie.\", \"Postęp, nie perfekcja. Dziś zrobiłaś krok naprzód.\", \"Skończyłaś jedną rzecz z listy. To o jedną więcej niż żadna.\", \"Jesteś dobrą mamą. To, że się o to martwisz, pokazuje, jak bardzo ci zależy.\", \"Jesteś kimś więcej niż tym, co zdążysz zrobić w ciągu dnia.\", \"Twoje dzieci nie potrzebują idealnej mamy. Potrzebują ciebie i mają ciebie.\", \"Bądź dla siebie tak cierpliwa, jak jesteś dla swoich dzieci.\", \"Masz prawo zajmować miejsce, czegoś chcieć i mieć własne marzenia.\", \"Błąd nie przekreśla miłości. Jutro jest nowy początek.\", \"Jesteś dla kogoś całym światem, a przy tym jesteś też sobą.\", \"Możesz nie kochać każdej minuty. I wciąż kochać swoje dzieci całym sercem.\", \"Nie ma jednego dobrego sposobu na bycie mamą. Twój sposób też jest w porządku.\", \"Jak w pozycji drzewa, możesz się chwiać. Znów odnajdziesz równowagę.\", \"Postaw mocno stopy jak w pozycji góry. Stoisz pewniej, niż ci się wydaje.\", \"Wojownik II: silne nogi, otwarte ramiona. To ty w tym tygodniu.\", \"Wdech na cztery, wydech na cztery. Jesteś tutaj i dobrze sobie radzisz.\", \"Rozciągnij się szeroko jak gwiazda. Masz prawo zajmować miejsce.\", \"Szeroki, niski przysiad trudno utrzymać. Długi dzień też. A ty go utrzymujesz.\", \"Możesz pochylić się jak sierp księżyca i nadal stać.\", \"Nie musisz jeszcze sięgać palców stóp. Każdy kawałek rozciągania się liczy.\", \"Pozycja trójkąta: jedna ręka w dół, druga w górę. Stój pewnie i sięgaj dalej.\", \"Jest późno. To, czego dziś nie zrobiłaś, może poczekać do jutra.\", \"Nie śpisz z dzieckiem o tej porze? Mnóstwo mam czuwa teraz razem z tobą.\", \"W domu jest cicho. Ta chwila należy do ciebie. Oddychaj.\", \"Przetrwałaś ten dzień. Tylko tego dziś było trzeba.\", \"Jeśli dziś w nocy myśli nie dają ci spokoju, zapisz je i niech poczekają do rana.\", \"Daj odpocząć oczom. Jutro możesz zacząć od nowa.\", \"Święta mogą być trudne, a nie tylko radosne. Cokolwiek czujesz w tym czasie, to w porządku.\", \"Stół nie musi być idealny. Liczą się ludzie, którzy przy nim siedzą.\", \"Jeśli w tym roku przy stole kogoś brakuje, bądź łagodna dla swojego serca.\", \"Dziękuję, mamo, za każdy posiłek, każde podwiezienie i każde przytulenie.\", \"Nie musisz przyjmować gości, piec ani uśmiechać się przez cały czas. Skromne święta to wciąż święta.\", \"Najlepszy prezent, jaki dostaną w tym roku twoje dzieci, to czas z tobą.\", \"Skromne święta też są pełne miłości. Nie trzeba dużo pieniędzy, żeby były wyjątkowe.\", \"Zimne dni, ciepłe przytulasy. To ty jesteś ciepłym miejscem w swoim domu.\", \"Możesz odpuścić część świątecznej gonitwy. Spokój to też prezent.\", \"Jeśli ten czas jest dla ciebie w tym roku ciężki, nie jesteś sama. Dzień po dniu.\"]";D.body.appendChild(e)})();
